import React, { useState } from "react"
import { blogApi } from "./api"
import { LikeButton } from "./LikeButton"
import type { BlogComment, BlogVisitorDto } from "./api"

interface CommentItemProps {
  comment: BlogComment
  visitor: BlogVisitorDto | null
  likedIds: Set<string>
  onReply: (parentId: string, replyToName: string) => void
  onDeleted: () => void
  isReply?: boolean
}

export function CommentItem({ comment, visitor, likedIds, onReply, onDeleted, isReply }: CommentItemProps) {
  const [deleting, setDeleting] = useState(false)
  const isOwn = visitor?.id === comment.author.id
  const deleted = comment.status === "deleted"

  const onDelete = async () => {
    if (deleting || !window.confirm("确定删除这条评论吗？")) return
    setDeleting(true)
    try {
      await blogApi.deleteComment(comment.id)
      onDeleted()
    } catch {
      window.alert("删除失败，请稍后再试")
    } finally {
      setDeleting(false)
    }
  }

  return (
    <div className={`flex gap-3 ${isReply ? "mt-3" : ""}`}>
      {comment.author.avatarUrl ? (
        <img src={comment.author.avatarUrl} alt={comment.author.login} className="w-8 h-8 rounded-full shrink-0" loading="lazy" />
      ) : (
        <div className="w-8 h-8 rounded-full shrink-0 bg-background-tertiary" />
      )}
      <div className="flex-1 min-w-0">
        <div className="flex items-center gap-2 text-xs">
          <span className="font-medium text-foreground">{comment.author.name || comment.author.login}</span>
          <span className="text-foreground-subtle">@{comment.author.login}</span>
          <span className="text-foreground-subtle">{new Date(comment.createdAt).toLocaleString("zh-CN")}</span>
        </div>
        {deleted ? (
          <p className="mt-1 text-sm text-foreground-subtle italic">该评论已删除</p>
        ) : (
          <p className="mt-1 text-sm text-foreground-secondary whitespace-pre-wrap wrap-break-word">{comment.content}</p>
        )}
        {!deleted && (
          <div className="mt-1.5 flex items-center gap-3">
            <LikeButton
              key={String(likedIds.has(comment.id))}
              targetType="comment"
              targetId={comment.id}
              initialCount={comment.likeCount}
              initialLiked={likedIds.has(comment.id)}
            />
            <button
              onClick={() => onReply(isReply ? comment.parentId! : comment.id, comment.author.name || comment.author.login)}
              className="text-xs text-foreground-subtle hover:text-accent transition-colors duration-200"
            >
              回复
            </button>
            {isOwn && (
              <button
                onClick={onDelete}
                disabled={deleting}
                className="text-xs text-foreground-subtle hover:text-accent transition-colors duration-200 disabled:opacity-50"
              >
                删除
              </button>
            )}
          </div>
        )}
      </div>
    </div>
  )
}
