/**
 * Bio component that queries for data
 * with Gatsby's StaticQuery component
 *
 * See: https://www.gatsbyjs.org/docs/static-query/
 */

import React from "react"
import { StaticQuery, graphql } from "gatsby"
import { GatsbyImage } from "gatsby-plugin-image"
import { GithubLogo } from "@phosphor-icons/react"

function Bio() {
    return (
        <StaticQuery
            query={bioQuery}
            render={(data) => {
                const { author, social } = data.site.siteMetadata
                return (
                    <div
                        style={{
                            display: `flex`,
                            alignItems: "center",
                        }}
                    >
                        <GatsbyImage
                            style={{
                                marginRight: "0.5rem",
                                marginBottom: 0,
                                minWidth: 50,
                                borderRadius: `100%`,
                            }}
                            imgStyle={{
                                borderRadius: `50%`,
                            }}
                            image={data.avatar.childImageSharp.gatsbyImageData}
                            alt={author}
                        />
                        <p className="flex flex-wrap items-center gap-x-1.5 gap-y-2 text-foreground-secondary">
                            <span>
                                Written by <strong className="text-foreground">{author}</strong>
                            </span>
                            <span aria-hidden="true" className="text-foreground-muted">·</span>
                            <span>Follow on</span>
                            <a
                                href={`https://github.com/${social.github}`}
                                target="_blank"
                                rel="external nofollow noopener noreferrer"
                                className="inline-flex items-center gap-1 rounded-md bg-accent-subtle px-2 py-1 text-sm font-semibold text-accent transition-colors duration-200 hover:bg-accent hover:text-accent-foreground"
                                aria-label={`Follow ${author} on GitHub`}
                            >
                                <GithubLogo weight="duotone" size={16} />
                                GitHub
                            </a>
                        </p>
                    </div>
                )
            }}
        />
    )
}

const bioQuery = graphql`
  query BioQuery {
    avatar: file(absolutePath: { regex: "/profile-pic.jpg/" }) {
      childImageSharp {
        gatsbyImageData(layout: FIXED, width: 50, height: 50, formats: [JPG])
      }
    }
    site {
      siteMetadata {
        author
        social {
          github
        }
      }
    }
  }
`

export default Bio
