import { useCallback, useEffect, useRef, useState } from "react"
import { blogApi, getApiBase, getToken, setToken } from "./api"
import type { BlogVisitorDto } from "./api"

interface BlogAuthState {
  visitor: BlogVisitorDto | null
  loading: boolean
}

export function useBlogAuth() {
  const [state, setState] = useState<BlogAuthState>({ visitor: null, loading: true })
  const seqRef = useRef(0)

  const refresh = useCallback(() => {
    const seq = ++seqRef.current
    blogApi
      .getMe()
      .then((visitor) => {
        if (seq === seqRef.current) setState({ visitor, loading: false })
      })
      .catch(() => {
        if (seq === seqRef.current) setState({ visitor: null, loading: false })
      })
  }, [])

  useEffect(() => {
    if (!getToken()) {
      setState({ visitor: null, loading: false })
      return
    }
    refresh()
  }, [refresh])

  useEffect(() => {
    const onMessage = (event: MessageEvent) => {
      if (event.origin !== new URL(getApiBase()).origin) return
      const data = event.data as { type?: string; token?: string }
      if (data?.type === "blog-auth" && data.token) {
        setToken(data.token)
        refresh()
      }
    }
    window.addEventListener("message", onMessage)
    return () => window.removeEventListener("message", onMessage)
  }, [refresh])

  const login = useCallback(() => {
    const origin = window.location.origin
    const w = 600
    const h = 700
    const left = window.screenX + (window.outerWidth - w) / 2
    const top = window.screenY + (window.outerHeight - h) / 2
    window.open(
      `${getApiBase()}/api/v1/blog/auth/github?origin=${encodeURIComponent(origin)}`,
      "blog-github-auth",
      `width=${w},height=${h},left=${left},top=${top},popup=1`
    )
  }, [])

  const logout = useCallback(() => {
    seqRef.current += 1
    setToken(null)
    setState({ visitor: null, loading: false })
  }, [])

  return { visitor: state.visitor, loading: state.loading, login, logout }
}
