import React from "react"
import { Link, graphql, PageProps } from "gatsby"
import { ArrowLeft, Clock, Calendar, BookOpen } from "@phosphor-icons/react"
import Bio from "../components/bio"
import Layout from "../components/layout"
import SEO from "../components/seo"
import { TableOfContents, PostEngagement } from "../components/blog"
import { CommentsSection } from "../components/comments"
import { useCodeCopy } from "../hooks"
import { tagSlug } from "../utils/tagSlug"

interface BlogPostPageContext {
  slug: string
  previous?: {
    fields: {
      slug: string
    }
    frontmatter: {
      title: string
    }
  }
  next?: {
    fields: {
      slug: string
    }
    frontmatter: {
      title: string
    }
  }
  // 系列上下文由 gatsby-node.ts 按标签匹配器推导注入；不属于任何系列时为 null
  series?: {
    id: string
    title: string
    index: number
    total: number
    prev: { slug: string; title: string } | null
    next: { slug: string; title: string } | null
  } | null
  // 相关文章由 gatsby-node.ts 构建期算好注入（top3，不足按日期最新补齐）
  related?: {
    slug: string
    title: string
    date: string
  }[]
}

interface BlogPostData {
  site: {
    siteMetadata: {
      title: string
      author: string
    }
  }
  markdownRemark: {
    id: string
    excerpt: string
    html: string
    tableOfContents: string
    wordCount: {
      words: number
      paragraphs: number
      sentences: number
    }
    fields: {
      slug: string
    }
    frontmatter: {
      title: string
      date: string
      description?: string
      tags?: string[]
    }
  }
}

const BlogPostTemplate: React.FC<
  PageProps<BlogPostData, BlogPostPageContext>
> = ({ data, pageContext, location }) => {
  const post = data.markdownRemark
  const siteTitle = data.site.siteMetadata.title
  const { previous, next, series, related } = pageContext

  // 中文技术文章按约 500 字/分钟估算，避免将中文字符按英文词速高估。
  const readingTime = Math.max(1, Math.ceil(post.wordCount.words / 500))

  // Add copy buttons to code blocks
  useCodeCopy()

  // KaTeX 样式体积较大，仅当正文包含公式（gatsby-remark-katex 渲染出 .katex 节点）时
  // 才通过动态 import 加载对应的异步 CSS chunk，避免进入文章页全局样式。
  const hasMath = post.html.includes('class="katex"')
  React.useEffect(() => {
    if (hasMath) {
      import("katex/dist/katex.min.css")
    }
  }, [hasMath])

  // 阅读进度条：passive scroll listener + rAF 节流，只写 transform 不触发布局；
  // prefers-reduced-motion 下保持隐藏（进度条本质是动效）。SSR 安全：window 仅在本 effect 内使用。
  const progressRef = React.useRef<HTMLDivElement>(null)
  React.useEffect(() => {
    const el = progressRef.current
    if (!el) {
      return
    }
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
      return
    }
    el.style.display = "block"
    let ticking = false
    const update = () => {
      ticking = false
      const scrollable =
        document.documentElement.scrollHeight - window.innerHeight
      const progress =
        scrollable > 0 ? Math.min(1, window.scrollY / scrollable) : 0
      el.style.transform = `scaleX(${progress})`
    }
    const onScroll = () => {
      if (!ticking) {
        ticking = true
        requestAnimationFrame(update)
      }
    }
    update()
    window.addEventListener("scroll", onScroll, { passive: true })
    window.addEventListener("resize", onScroll, { passive: true })
    return () => {
      window.removeEventListener("scroll", onScroll)
      window.removeEventListener("resize", onScroll)
    }
  }, [])

  return (
    <article>
      {/* 阅读进度：顶部 2px accent 细线，z-[60] 压在吸顶 Header(z-50) 之上；全局弹层(SearchModal z-[70])仍在更上层 */}
      <div
        ref={progressRef}
        aria-hidden="true"
        className="fixed top-0 left-0 z-60 h-0.5 w-full bg-accent"
        style={{
          display: "none",
          transform: "scaleX(0)",
          transformOrigin: "left",
        }}
      />
      <Layout location={location} title={siteTitle}>
        {/* xl 起正文 + 目录双栏网格：目录列宽 auto（收起时自动让位），正文列 min-w-0 防止代码块撑破网格 */}
        <div className="xl:grid xl:grid-cols-[minmax(0,1fr)_auto] xl:gap-10">
        <div className="min-w-0">
        <SEO
          title={post.frontmatter.title}
          description={post.frontmatter.description || post.excerpt}
        />

        {/* Breadcrumb Navigation */}
        <nav className="fade-in mb-6" aria-label="Breadcrumb">
          <Link
            to="/"
            className="inline-flex items-center text-xs text-foreground-muted hover:text-accent transition-colors duration-200 group"
          >
            <ArrowLeft className="w-3.5 h-3.5 mr-1 transition-transform duration-200 group-hover:-translate-x-1" weight="duotone" />
            返回首页
          </Link>
        </nav>

        {/* Article Header */}
        <header className="mb-8 fade-in">
          {/* Series Badge */}
          {series && (
            <div className="mb-3">
              <Link
                to={`/series/${series.id}/`}
                className="inline-flex items-center gap-1.5 text-xs text-foreground-muted hover:text-accent transition-colors duration-200 group"
              >
                <BookOpen className="w-3.5 h-3.5 text-accent" weight="duotone" />
                <span>
                  《{series.title}》· 第 {series.index} 篇 · 共 {series.total} 篇
                </span>
              </Link>
            </div>
          )}

          {/* Title - Noto Serif SC */}
          <h1
            className="text-xl sm:text-2xl lg:text-3xl font-bold text-foreground leading-tight mb-4"
            style={{ fontFamily: '"Noto Serif SC", Georgia, "Times New Roman", serif' }}
          >
            {post.frontmatter.title}
          </h1>

          {/* Meta Information Row */}
          <div className="flex flex-wrap items-center gap-3 text-xs text-foreground-muted">
            {/* Date */}
            <div className="flex items-center gap-1.5">
              <Calendar className="w-4 h-4 text-foreground-subtle" weight="duotone" />
              <time>{post.frontmatter.date}</time>
            </div>

            {/* Reading Time */}
            <div className="flex items-center gap-1.5">
              <Clock className="w-4 h-4 text-foreground-subtle" weight="duotone" />
              <span>{readingTime} 分钟阅读</span>
            </div>

            {/* Tags */}
            {post.frontmatter.tags && post.frontmatter.tags.length > 0 && (
              <>
                <span className="text-foreground-muted">·</span>
                <div className="flex flex-wrap gap-1.5">
                  {post.frontmatter.tags.map((tag) => (
                    <Link
                      key={tag}
                      to={`/tags/${tagSlug(tag)}/`}
                      className="inline-flex items-center px-2 py-0.5 text-[11px] font-medium text-accent bg-accent-subtle rounded-full hover:bg-accent hover:text-accent-foreground transition-colors duration-200"
                      style={{ borderRadius: '12px 16px 10px 18px' }}
                    >
                      #{tag}
                    </Link>
                  ))}
                </div>
              </>
            )}
          </div>

          {/* Standfirst 引言：frontmatter.description，排版层级区分，无左边框 */}
          {post.frontmatter.description && (
            <p className="mt-5 font-serif text-lg text-foreground-secondary leading-relaxed">
              {post.frontmatter.description}
            </p>
          )}

        </header>

        {/* Article Content - Noto Sans SC */}
        <div
          className="prose max-w-none fade-in article-content text-foreground"
          style={{
            fontFamily: '"Noto Sans SC", system-ui, -apple-system, sans-serif',
          }}
          dangerouslySetInnerHTML={{ __html: post.html }}
        />

        {/* Reading Stats & Engagement */}
        <hr className="my-8 border-theme-subtle" />
        <PostEngagement
          postPath={post.fields.slug}
          words={post.wordCount.words}
          paragraphs={post.wordCount.paragraphs}
        />

        {/* Author Bio */}
        <div className="mb-10">
          <Bio />
        </div>

        {/* Previous/Next Navigation */}
        <nav
          className="grid grid-cols-1 sm:grid-cols-2 gap-3 mb-10"
          aria-label="文章导航"
        >
          {/* Previous Post */}
          <div className="sm:col-start-1">
            {previous && (
              <Link
                to={previous.fields.slug}
                rel="prev"
                className="group block p-3.5 sm:p-4 rounded-xl bg-background-secondary hover:bg-background-tertiary transition-all duration-200 min-h-[40px]"
              >
                <span className="text-[11px] text-foreground-muted mb-1.5 block flex items-center gap-1">
                  <ArrowLeft className="w-3 h-3" weight="bold" />
                  上一篇
                </span>
                <span className="text-xs font-medium text-foreground group-hover:text-accent transition-colors line-clamp-2">
                  {previous.frontmatter.title}
                </span>
              </Link>
            )}
          </div>

          {/* Next Post */}
          <div className="sm:col-start-2 sm:text-right">
            {next && (
              <Link
                to={next.fields.slug}
                rel="next"
                className="group block p-3.5 sm:p-4 rounded-xl bg-background-secondary hover:bg-background-tertiary transition-all duration-200 min-h-[40px]"
              >
                <span className="text-[11px] text-foreground-muted mb-1.5 block flex items-center justify-end gap-1">
                  下一篇
                  <ArrowLeft className="w-3 h-3 rotate-180" weight="bold" />
                </span>
                <span className="text-xs font-medium text-foreground group-hover:text-accent transition-colors line-clamp-2">
                  {next.frontmatter.title}
                </span>
              </Link>
            )}
          </div>
        </nav>

        {/* Series Navigation：系列内 prev/next，无则缺省 */}
        {series && (series.prev || series.next) && (
          <nav
            className="grid grid-cols-1 sm:grid-cols-2 gap-3 mb-10"
            aria-label="系列导航"
          >
            <div className="sm:col-span-2 flex items-center gap-1.5 text-[11px] text-foreground-muted">
              <BookOpen className="w-3 h-3 text-accent" weight="duotone" />
              <Link
                to={`/series/${series.id}/`}
                className="hover:text-accent transition-colors duration-200"
              >
                《{series.title}》
              </Link>
              <span>· 第 {series.index} 篇 · 共 {series.total} 篇</span>
            </div>
            <div className="sm:col-start-1">
              {series.prev && (
                <Link
                  to={series.prev.slug}
                  rel="prev"
                  className="group block p-3.5 sm:p-4 rounded-xl bg-background-secondary hover:bg-background-tertiary transition-all duration-200 min-h-[40px]"
                >
                  <span className="text-[11px] text-foreground-muted mb-1.5 block flex items-center gap-1">
                    <ArrowLeft className="w-3 h-3" weight="bold" />
                    系列上一篇
                  </span>
                  <span className="text-xs font-medium text-foreground group-hover:text-accent transition-colors line-clamp-2">
                    {series.prev.title}
                  </span>
                </Link>
              )}
            </div>
            <div className="sm:col-start-2 sm:text-right">
              {series.next && (
                <Link
                  to={series.next.slug}
                  rel="next"
                  className="group block p-3.5 sm:p-4 rounded-xl bg-background-secondary hover:bg-background-tertiary transition-all duration-200 min-h-[40px]"
                >
                  <span className="text-[11px] text-foreground-muted mb-1.5 block flex items-center justify-end gap-1">
                    系列下一篇
                    <ArrowLeft className="w-3 h-3 rotate-180" weight="bold" />
                  </span>
                  <span className="text-xs font-medium text-foreground group-hover:text-accent transition-colors line-clamp-2">
                    {series.next.title}
                  </span>
                </Link>
              )}
            </div>
          </nav>
        )}

        {/* Related Posts：构建期注入 top3，无相关时整段不渲染 */}
        {related && related.length > 0 && (
          <section className="mb-10" aria-label="相关文章">
            <h2 className="text-sm font-bold text-foreground font-serif mb-3">
              相关文章
            </h2>
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
              {related.map((item) => (
                <Link
                  key={item.slug}
                  to={item.slug}
                  className="group block p-4 bg-background-card rounded-2xl shadow-xs hover:shadow-md transition-shadow duration-200"
                >
                  <span className="text-xs font-medium text-foreground group-hover:text-accent transition-colors line-clamp-2">
                    {item.title}
                  </span>
                  <time className="mt-2 block text-[11px] text-foreground-muted tabular-nums">
                    {item.date}
                  </time>
                </Link>
              ))}
            </div>
          </section>
        )}

        {/* Comments - self-hosted engagement system */}
        <CommentsSection postPath={post.fields.slug} />
        </div>

        {/* Table of Contents：xl 起作为网格右栏 sticky 展示，小屏隐藏 */}
        <TableOfContents html={post.tableOfContents} />
        </div>
      </Layout>
    </article>
  )
}

export default BlogPostTemplate

export const pageQuery = graphql`
  query BlogPostBySlug($slug: String!) {
    site {
      siteMetadata {
        title
        author
      }
    }
    markdownRemark(fields: { slug: { eq: $slug } }) {
      id
      excerpt(pruneLength: 160)
      html
      fields {
        slug
      }
      tableOfContents
      frontmatter {
        title
        date(formatString: "YYYY年MM月DD日")
        description
        tags
      }
      wordCount {
        words
        paragraphs
        sentences
      }
    }
  }
`
