import React, { useCallback, useEffect, useRef, useState } from "react"
import { GithubLogo, SignOut } from "@phosphor-icons/react"
import { blogApi } from "./api"
import { useBlogAuth } from "./useBlogAuth"
import { CommentItem } from "./CommentItem"
import type { BlogComment } from "./api"

interface CommentsSectionProps {
  postPath: string
}

export function CommentsSection({ postPath }: CommentsSectionProps) {
  const { visitor, loading: authLoading, login, logout } = useBlogAuth()
  const [comments, setComments] = useState<BlogComment[]>([])
  const [likedIds, setLikedIds] = useState<Set<string>>(new Set())
  const [content, setContent] = useState("")
  const [replyTo, setReplyTo] = useState<{ parentId: string; name: string } | null>(null)
  const [submitting, setSubmitting] = useState(false)
  const [error, setError] = useState("")
  const [mounted, setMounted] = useState(false)
  const textareaRef = useRef<HTMLTextAreaElement>(null)

  const load = useCallback(async () => {
    try {
      const list = await blogApi.getComments(postPath)
      const ids = list.flatMap((c) => [c.id, ...(c.replies ?? []).map((r) => r.id)])
      let likes: Awaited<ReturnType<typeof blogApi.getLikes>> = []
      try {
        if (ids.length) likes = await blogApi.getLikes("comment", ids)
      } catch {
        // 点赞状态获取失败不影响评论列表渲染
      }
      // 同一批次更新，保证 LikeButton 挂载时即拿到正确的 initialLiked
      setLikedIds(new Set(likes.filter((l) => l.likedByMe).map((l) => l.targetId)))
      setComments(list)
    } catch {
      // 列表加载失败静默处理，保持页面可用
    }
    // visitor?.id 变化（登录/退出）时重新拉取 likedByMe 状态
  }, [postPath, visitor?.id])

  useEffect(() => {
    setMounted(true)
    void load()
  }, [load])

  const onReply = useCallback((parentId: string, name: string) => {
    setReplyTo({ parentId, name })
    textareaRef.current?.focus()
  }, [])

  const onSubmit = async () => {
    if (!content.trim() || submitting) return
    setSubmitting(true)
    setError("")
    try {
      await blogApi.postComment({ postPath, content: content.trim(), parentId: replyTo?.parentId })
      setContent("")
      setReplyTo(null)
      await load()
    } catch (e) {
      setError(e instanceof Error ? e.message : "评论失败，请稍后再试")
    } finally {
      setSubmitting(false)
    }
  }

  // SSR：服务端渲染占位，客户端挂载后渲染真实内容
  if (!mounted) {
    return <section className="rounded-xl bg-background-secondary p-4 sm:p-6 shadow-xs" />
  }

  return (
    <section className="rounded-xl bg-background-secondary p-4 sm:p-6 shadow-xs" style={{ borderRadius: "16px 20px 14px 22px" }}>
      <div className="flex items-center justify-between mb-6">
        <h3 className="text-lg font-semibold text-foreground" style={{ fontFamily: '"Noto Serif SC", Georgia, "Times New Roman", serif' }}>
          评论与讨论
        </h3>
        {visitor && (
          <div className="flex items-center gap-2">
            {visitor.avatarUrl && <img src={visitor.avatarUrl} alt={visitor.login} className="w-6 h-6 rounded-full" />}
            <span className="text-xs text-foreground-muted">{visitor.name || visitor.login}</span>
            <button onClick={logout} className="text-foreground-subtle hover:text-accent transition-colors" title="退出登录" aria-label="退出登录">
              <SignOut className="w-4 h-4" weight="duotone" />
            </button>
          </div>
        )}
      </div>

      {authLoading ? null : visitor ? (
        <div className="mb-6">
          {replyTo && (
            <div className="mb-2 flex items-center gap-2 text-xs text-foreground-muted">
              <span>回复 @{replyTo.name}</span>
              <button onClick={() => setReplyTo(null)} className="text-foreground-subtle hover:text-accent">取消</button>
            </div>
          )}
          <textarea
            ref={textareaRef}
            value={content}
            onChange={(e) => setContent(e.target.value)}
            placeholder="写下你的想法…"
            rows={3}
            maxLength={2000}
            className="w-full px-3 py-2 text-sm rounded-lg bg-background-tertiary text-foreground placeholder:text-foreground-subtle outline-hidden focus:ring-1 focus:ring-accent resize-y"
          />
          <div className="mt-2 flex items-center justify-between">
            <span className="text-xs text-foreground-subtle">{error || `${content.length}/2000`}</span>
            <button
              onClick={onSubmit}
              disabled={submitting || !content.trim()}
              className="px-4 py-1.5 text-sm rounded-lg bg-accent text-accent-foreground hover:opacity-90 transition-opacity disabled:opacity-50"
            >
              {submitting ? "发布中…" : "发布"}
            </button>
          </div>
        </div>
      ) : (
        <button
          onClick={login}
          className="mb-6 inline-flex items-center gap-2 px-4 py-2 text-sm rounded-lg bg-background-tertiary text-foreground hover:shadow-md transition-shadow duration-200"
        >
          <GithubLogo className="w-4 h-4" weight="duotone" />
          使用 GitHub 登录后评论
        </button>
      )}

      <div className="space-y-5">
        {comments.map((comment) => (
          <div key={comment.id}>
            <CommentItem comment={comment} visitor={visitor} likedIds={likedIds} onReply={onReply} onDeleted={load} />
            {comment.replies && comment.replies.length > 0 && (
              <div className="ml-11 mt-3 space-y-3">
                {comment.replies.map((reply) => (
                  <CommentItem key={reply.id} comment={reply} visitor={visitor} likedIds={likedIds} onReply={onReply} onDeleted={load} isReply />
                ))}
              </div>
            )}
          </div>
        ))}
        {!comments.length && <p className="text-sm text-foreground-subtle">还没有评论，来抢沙发～</p>}
      </div>
    </section>
  )
}
